// Known points-per-Sphinx by army variety, as established by the examples so
// far. Deliberately a table, not a formula: the remaining examples decide the
// true shape of the rule.
const POINTS_PER_SPHINX_BY_VARIETY: ReadonlyArray<{
  readonly atLeastTypes: number;
  readonly points: number;
}> = [
  { atLeastTypes: 6, points: 5 },
  { atLeastTypes: 4, points: 3 },
  { atLeastTypes: 0, points: 2 },
];

const scorePerSphinx = (monsterTypeCount: number): number =>
  POINTS_PER_SPHINX_BY_VARIETY.find(
    (step) => monsterTypeCount >= step.atLeastTypes,
  )!.points;

